"use strict";(globalThis.webpackChunkdocs_next=globalThis.webpackChunkdocs_next||[]).push([[85126],{25585(e){e.exports=JSON.parse('{"tag":{"label":"crossplane","permalink":"/docs-next/pr-preview/pr-452/docs/tags/crossplane","allTagsPath":"/docs-next/pr-preview/pr-452/docs/tags","count":2,"items":[{"id":"blueprints/by-use-case/platform-engineering/crossplane/crossplane","title":"Crossplane","description":"Crossplane is an open-source framework for building cloud-native control planes and internal developer platforms. It extends the Kubernetes API and reconciliation model beyond workloads running inside a Kubernetes cluster, allowing Kubernetes to manage external resources such as virtual machines, networks, databases, Kubernetes clusters, and other cloud or API-based services. Platform teams can therefore expose infrastructure through declarative APIs while Crossplane continuously works to keep the actual infrastructure aligned with the desired state.","permalink":"/docs-next/pr-preview/pr-452/docs/blueprints/by-use-case/platform-engineering/crossplane/crossplane"},{"id":"blueprints/by-use-case/platform-engineering/crossplane/introduction-crossplane-provider","title":"Introduction to the T Cloud Public Crossplane Provider","description":"Crossplane extends Kubernetes into a control plane for managing cloud infrastructure and services through Kubernetes-style APIs. Running as an operator in virtually any Kubernetes environment (including CCE, OpenShift, and local clusters such as kind), it continuously reconciles declared resources with their desired state. Combined with GitOps workflows and tools such as Helm, Helmfile, and Argo CD, Crossplane provides a Kubernetes-native approach to provisioning and managing T Cloud Public services such as VPC, ECS, CCE, RDS, and OBS.","permalink":"/docs-next/pr-preview/pr-452/docs/blueprints/by-use-case/platform-engineering/crossplane/introduction-crossplane-provider"}],"unlisted":false}}')}}]);